using System.ClientModel;
using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration – set OPENAI_API_KEY (or AZURE_OPENAI_API_KEY + endpoint) and
// optionally OPENAI_MODEL before running.
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
var model  = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Set the OPENAI_API_KEY environment variable to run this agent.");
    return 1;
}

IChatClient innerClient = new OpenAIClient(new ApiKeyCredential(apiKey))
    .GetChatClient(model)
    .AsIChatClient();

// Register the two tools the agent can invoke.
var searchTool = new WebSearchTool();
var notesTool  = new NotesTool();

using IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var tools = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(searchTool.SearchWeb),
        AIFunctionFactory.Create(notesTool.SaveNote),
        AIFunctionFactory.Create(notesTool.ReadNotes),
    ],
};

// ---------------------------------------------------------------------------
// Agent loop – ask the user for a topic, then let the agent research it.
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        🔍  AI Research Agent  🔍        ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  I will search the web, take notes, and ║");
Console.WriteLine("║  produce a summary on any topic you ask ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Enter a research topic (or 'quit' to exit): ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notesTool.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, """
            You are a research agent. Your goal is to thoroughly research a topic
            the user provides by using the tools available to you.

            Follow this workflow:
            1. Use search_web 2-3 times with different queries to gather information.
            2. After each search, use save_note to record the key facts you found.
            3. Use read_notes to review everything you have collected.
            4. Produce a well-structured summary with sections, citing sources where
               possible.

            Be thorough but concise.
            """),
        new(ChatRole.User, $"Please research this topic: {topic}"),
    };

    Console.WriteLine($"\n🔎 Researching \"{topic}\" …\n");

    var response = await agent.GetResponseAsync(messages, tools);

    Console.WriteLine("═══════════════  RESEARCH SUMMARY  ═══════════════");
    Console.WriteLine(response.Text);
    Console.WriteLine("══════════════════════════════════════════════════\n");
}

return 0;

// ═══════════════════════════════════════════════════════════════════════════
// Tool: Web Search – performs a Bing-style web search via an HTTP scrape.
// ═══════════════════════════════════════════════════════════════════════════
sealed class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" },
            { "Accept-Language", "en-US,en;q=0.9" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information. Returns the top search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);
            var snippets = ExtractSnippets(html, maxResults: 5);

            if (snippets.Count == 0)
                return "No results found.";

            return string.Join("\n\n", snippets.Select((s, i) => $"[{i + 1}] {s}"));
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<string> ExtractSnippets(string html, int maxResults)
    {
        // Parse lightweight snippets from DuckDuckGo HTML results.
        var results = new List<string>();
        var marker = "class=\"result__snippet";
        var pos = 0;
        while (results.Count < maxResults)
        {
            pos = html.IndexOf(marker, pos, StringComparison.Ordinal);
            if (pos < 0) break;

            var gt = html.IndexOf('>', pos);
            if (gt < 0) break;

            var end = html.IndexOf('<', gt + 1);
            if (end < 0) break;

            var snippet = html[(gt + 1)..end].Trim();
            snippet = System.Net.WebUtility.HtmlDecode(snippet);
            if (!string.IsNullOrWhiteSpace(snippet))
                results.Add(snippet);

            pos = end;
        }

        // Also grab result titles + URLs for citations.
        var titleMarker = "class=\"result__a";
        pos = 0;
        var titleIndex = 0;
        while (titleIndex < results.Count)
        {
            pos = html.IndexOf(titleMarker, pos, StringComparison.Ordinal);
            if (pos < 0) break;

            var hrefStart = html.LastIndexOf("href=\"", pos, Math.Min(pos, 200), StringComparison.Ordinal);
            var titleGt = html.IndexOf('>', pos);
            if (titleGt < 0) break;

            var titleEnd = html.IndexOf('<', titleGt + 1);
            if (titleEnd < 0) break;

            var title = System.Net.WebUtility.HtmlDecode(html[(titleGt + 1)..titleEnd].Trim());
            if (!string.IsNullOrWhiteSpace(title))
                results[titleIndex] = $"{title} — {results[titleIndex]}";

            titleIndex++;
            pos = titleEnd;
        }

        return results;
    }
}

