// Tool: Notes – lets the agent store and recall research notes.
// ═══════════════════════════════════════════════════════════════════════════
sealed class NotesTool
{
    private readonly List<string> _notes = [];

    [Description("Save a research note. Use this to record key facts discovered during research.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Read all research notes collected so far.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  📖 Reading {_notes.Count} note(s)");
        return string.Join("\n---\n",
            _notes.Select((n, i) => $"Note {i + 1}:\n{n}"));
    }

    public void Clear() => _notes.Clear();
}

